#include <chrono>
#include <ctime>
#include <sstream>
#include <format>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    using namespace std::chrono;
    auto start = steady_clock::now();
    auto finish = steady_clock::now();
    assert(finish >= start);
    auto precise = high_resolution_clock::now();
    (void)precise;
    auto now = system_clock::now();
    std::time_t time = system_clock::to_time_t(now);
    (void)time;
    std::clock_t ticks = std::clock();
    (void)ticks;
    auto file = file_clock::now();
    auto system = file_clock::to_sys(file);
    auto roundtrip = file_clock::from_sys(system);
    assert(roundtrip == file);
    auto text = std::format("{}", system);
    assert(!text.empty());
    std::ostringstream output;
    output << system;
    assert(!output.str().empty());
}
